ALTER TABLE public.leads ADD COLUMN IF NOT EXISTS email_marketing_opt_in boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS email_marketing_opt_in_at timestamptz, ADD COLUMN IF NOT EXISTS email_marketing_opt_in_version text;
CREATE OR REPLACE FUNCTION public.stamp_lead_email_consent() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.email_marketing_opt_in THEN NEW.email_marketing_opt_in_at := now(); NEW.email_marketing_opt_in_version := 'admissions-email-2026-10-27-v1'; ELSE NEW.email_marketing_opt_in_at := NULL; NEW.email_marketing_opt_in_version := NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER stamp_lead_email_consent BEFORE INSERT OR UPDATE OF email_marketing_opt_in ON public.leads FOR EACH ROW EXECUTE FUNCTION public.stamp_lead_email_consent();
COMMENT ON COLUMN public.leads.email_marketing_opt_in IS 'Explicit optional email marketing consent; existing leads are not opted in. Sending requires a dedicated marketing provider.';